26	func eval(t *testing.T, cfgRaw, key, ctxRaw string) EvalResult {
27		t.Helper()
28		cfg := mustParseConfig(t, cfgRaw)
29		ctx := mustParseContext(t, ctxRaw)
30		flag := cfg.Find(key)
31		if flag == nil {
