37	func TestEvaluateDisabled(t *testing.T) {
38		// 即使 default=true 且规则命中，关闭的开关固定 false。
39		cfg := `{"flags":[{"key":"f","enabled":false,"default":true,"rules":[
40			{"id":"r1","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]}]}]}`
41		got := eval(t, cfg, "f", `{"plan":"pro"}`)
42		want := EvalResult{Key: "f", Value: false, Reason: EvalDisabled, RuleID: nil}
