50			{"id":"r1","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"pro"}]},
51			{"id":"r2","value":false,"conditions":[{"attribute":"tier","op":"in","value":["a","b"]}]}]}]}`
52		// 首条全中规则获胜，r1 命中即采用其 value=true，r2 不再考虑。
53		got := eval(t, cfg, "f", `{"plan":"pro","tier":"a"}`)
