93			`{"plan":" Pro"}`: "whitespace", // 不裁剪空白
94			`{}`:              "missing",
95		}
96		for ctxRaw, label := range cases {
97			got := eval(t, cfg, "f", ctxRaw)
98			matched := got.Reason == EvalRule
99			wantMatch := label == "match"
