// 字符串值），拒绝无法组成完整字符的 Unicode 转义：孤立的高代理项、孤立的低代理项，
// 以及不完整或顺序错误的代理项对。encoding/json 会把这类转义静默替换成 U+FFFD，
// 使 "\uD800" 与真正的 "�" 无法区分、不同坏字段名解码后撞名，因此必须在解码前
// 基于原文检查。label 是根对象的位置前缀（"config" 或 "context"）。
// JSON 语法错误（如 \u 后不是 4 位十六进制）不在此报告，留给 Unmarshal。
func validateUnicodeEscapes(raw []byte, label string) error {
	type frame struct {
		path      string
		object    bool
		expectKey bool
		nextIndex int
		lastKey   string
	}
	var stack []*frame
	childPath := func() string {
		if len(stack) == 0 {
			return label
		}
		top := stack[len(stack)-1]
		if top.object {
			return top.path + "." + top.lastKey
		}
		return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
	}
	i := 0
	for i < len(raw) {
		switch c := raw[i]; c {
		case '{', '[':
			f := &frame{path: childPath(), object: c == '{', expectKey: true}
			stack = append(stack, f)
			i++
		case '}', ']':
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
			i++
		case ',':
			if len(stack) > 0 {
				top := stack[len(stack)-1]
				if top.object {
					top.expectKey = true
				} else {
					top.nextIndex++
				}
			}
			i++
		case ':':
			if len(stack) > 0 {
				stack[len(stack)-1].expectKey = false
			}
			i++
		case '"':
			end, bad := scanStringEscapes(raw, i)
			if end < 0 {
				// 字符串未闭合，语法错误留给 Unmarshal。
				return nil
			}
			isKey := len(stack) > 0 && stack[len(stack)-1].object && stack[len(stack)-1].expectKey
			if bad != "" {
				if isKey {
					return fmt.Errorf("%s: field name %s contains invalid Unicode escape %s: surrogate escape does not form a complete character",
						stack[len(stack)-1].path, rawKeyForMessage(raw[i:end]), bad)
				}
				return fmt.Errorf("%s: invalid Unicode escape %s: surrogate escape does not form a complete character", childPath(), bad)
			}
