				top := stack[len(stack)-1]
				var name string
				if err := json.Unmarshal(raw[i:end], &name); err == nil {
					top.lastKey = name
				}
				top.expectKey = false
			}
			i = end
		default:
			i++
		}
	}
	return nil
}
```

