// 报告，留给 Unmarshal。
func validateUnicodeEscapes(raw []byte, label string) error {
	type frame struct {
		path      string
		object    bool
		expectKey bool
		nextIndex int
		lastKey   string
	}
	var stack []*frame
	childPath := func() string {
		if len(stack) == 0 {
			return label
		}
