	cfgLiteral := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
		{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"😀"}]}]}]}`
	if got := eval(t, cfgLiteral, "f", `{"a":"😀"}`); got.Reason != EvalRule {
